def agora():
    return datetime.now().strftime("%d/%m/%Y %H:%M:%S")


def normalizar(txt):
    txt = str(txt or "").lower()
    trocas = {
        "ç": "c", "ã": "a", "á": "a", "à": "a", "â": "a",
        "é": "e", "ê": "e", "í": "i", "ó": "o", "ô": "o",
        "õ": "o", "ú": "u"
    }
    for a, b in trocas.items():
        txt = txt.replace(a, b)
    return txt


def log(msg, tipo="INFO"):
    linha = f"[{agora()}] {tipo}: {msg}"

    with TERMINAL_LOCK:
        TERMINAL_BUFFER.append(linha)
        try:
            with LOG_FILE.open("a", encoding="utf-8", errors="replace") as f:
                f.write(linha + "\n")
                f.flush()
        except Exception as e:
            print(f"[{agora()}] ERRO_LOG: {e}", flush=True)

    print(linha, flush=True)


def limpar_terminal():
    with TERMINAL_LOCK:
        TERMINAL_BUFFER.clear()
        try:
            LOG_FILE.write_text("", encoding="utf-8")
        except Exception:
            pass


def ler_terminal():
    with TERMINAL_LOCK:
        if TERMINAL_BUFFER:
            return "\n".join(TERMINAL_BUFFER)

    if LOG_FILE.exists():
        try:
            linhas = LOG_FILE.read_text(encoding="utf-8", errors="replace").splitlines()
            if linhas:
                return "\n".join(linhas[-1000:])
        except Exception as e:
            return f"Erro ao ler terminal: {e}"

    return ""


def load_config():
    if not CONFIG_FILE.exists():
        raise FileNotFoundError(f"Arquivo de configuração não encontrado: {CONFIG_FILE}")
    return json.loads(CONFIG_FILE.read_text(encoding="utf-8"))


def salvar_status(data):
    STATUS_FILE.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")


def resolver_caminho_script(robo):
    """Retorna o primeiro caminho existente para o robô.

    Mantém compatibilidade com nomes antigos que possam ainda estar gravados
    no status.json ou em versões anteriores do portal.
    """
    principal = Path(robo["script"])

    alternativas = {
        "comercial_cadastro_vendedores": [
            Path(r"\\192.168.1.139\Controladoria\BI_Granja\Agrosys_Extractor\Comercial\cadastro_de_vendedores.py"),
            Path(r"\\192.168.1.139\Controladoria\BI_Granja\Agrosys_Extractor\Comercial\comercial_cadastro_vendedores.py"),
        ],
        "tratamento_comercial": [
            Path(r"\\192.168.1.139\Controladoria\BI_Granja\Python\Comercial\Tratar_Comercial.py"),
            Path(r"\\192.168.1.139\Controladoria\BI_Granja\Agrosys_Extractor\Comercial\Tratar_Comercial.py"),
        ],
    }

    candidatos = [principal]
    candidatos.extend(alternativas.get(robo.get("id"), []))

    vistos = set()
    for candidato in candidatos:
        chave = str(candidato).lower()
        if chave in vistos:
            continue
        vistos.add(chave)

        if candidato.exists():
            return candidato

    # Retorna o principal para que a mensagem de erro mostre o caminho oficial.
    return principal



