def robo_por_id_ou_nome(chave):
    chave = str(chave or "")
    chave_norm = normalizar(chave)

    aliases = {
        "vendedores": "cadastro_vendedores",
        "veiculos": "relatorio_veiculos",
        "pallets": "controle_pallets",
        "ctrl_frete": "controle_frete",
        "ocorrencias": "ocorrencia_viagens_custo",
        "faturamento": "faturamento_cfop",
        "tratamento": "tratamento_logistica",
        "comercial": "comercial_faturamento_cfop",
        "comercial_cfop": "comercial_faturamento_cfop",
        "cadastro_comercial": "comercial_cadastro_vendedores",
        "clientes_cadastrados": "comercial_clientes_cadastrados",
        "clientes_comercial": "comercial_clientes_cadastrados",
        "tratamento_comercial": "tratamento_comercial",
        "suprimentos": "suprimentos_contas_pagas",
        "contas_pagas": "suprimentos_contas_pagas",
        "ordens_compras": "suprimentos_ordens_compras",
        "ordens_de_compras": "suprimentos_ordens_compras",
        "relatorio_usuarios": "suprimentos_relatorio_usuarios",
        "usuarios_suprimentos": "suprimentos_relatorio_usuarios",
        "solicitacoes_requisitante": "suprimentos_solicitacoes_requisitante",
        "solicitacoes_por_requisitante": "suprimentos_solicitacoes_requisitante",
        "requisitante": "suprimentos_solicitacoes_requisitante",
        "titulos_agrupados": "suprimentos_titulos_agrupados",
        "titulos": "suprimentos_titulos_agrupados",
        "relacao_oc_nf": "suprimentos_relacao_oc_nf",
        "oc_nf": "suprimentos_relacao_oc_nf",
        "notas_fiscais_item": "suprimentos_notas_fiscais_item",
        "notas_item": "suprimentos_notas_fiscais_item",
        "nf_item": "suprimentos_notas_fiscais_item",
        "tratamento_suprimentos": "tratamento_suprimentos",
        "avenova_turnos": "pcp_diario_industria_avenova_turnos",
        "indice_zootecnico": "indice_zootecnico_base_dinamica",
        "base_dinamica": "indice_zootecnico_base_dinamica",
        "lotes_abertos": "indice_zootecnico_mortalidade_peso_lotes_abertos",
        "lotes_fechados": "indice_zootecnico_mortalidade_peso_lotes_fechados",
        "tratamento_indice_zootecnico": "tratamento_indice_zootecnico",
    }

    por_id = {r["id"]: r for r in get_robos()}

    if chave in por_id:
        return por_id[chave]

    if chave in aliases:
        return por_id.get(aliases[chave])

    for r in get_robos():
        if normalizar(r["nome"]) == chave_norm:
            return r

    return None


def robos_por_modulo(modulo):
    return [r for r in get_robos() if r.get("modulo") == modulo]


def ordem_logistica():
    # Somente robôs de extração. O tratamento entra no final da fila completa.
    return [
        r["id"]
        for r in robos_por_modulo("logistica")
        if r["id"] != "tratamento_logistica"
    ]


