try:
    from powerbi_api import PowerBIClient, PowerBIConfigError
except Exception:
    PowerBIClient = None

    class PowerBIConfigError(Exception):
        pass

def tratamento_modo_requisicao(body):
    modo = str((body or {}).get("tratamento_modo", "incremental") or "incremental").strip().lower()
    if modo not in {"incremental", "completo"}:
        modo = "incremental"
    return modo


