# =============================================================================
# BI AGENT — ENDPOINTS PRIVADOS (V1)
#
# O Agent roda dentro da rede da Granja e acessa estes endpoints somente por
# HTTPS de saída. Ele NÃO usa login de usuário e NÃO recebe DATABASE_URL.
# A credencial própria fica em PORTAL_BI_AGENT_KEY no Render e no ambiente
# local do Agent. Nenhum caminho de script é enviado pelo servidor.
# =============================================================================

def _agent_autorizado():
    esperado = str(os.getenv("PORTAL_BI_AGENT_KEY") or "").strip()
    recebido = str(request.headers.get("X-Agent-Key") or "").strip()
    if not esperado or len(esperado) < 32:
        raise RuntimeError(
            "PORTAL_BI_AGENT_KEY não configurada corretamente no ambiente da API."
        )
    return bool(recebido) and hmac.compare_digest(recebido, esperado)


def _resposta_agent_nao_autorizado():
    return jsonify({
        "ok": False,
        "erro": "Agent não autorizado."
    }), 401


@app.route("/api/agent/jobs/claim", methods=["POST"])
def api_agent_claim_job():
    """Reserva atomicamente o próximo job aguardando e inicia o heartbeat."""
    try:
        if not _agent_autorizado():
            return _resposta_agent_nao_autorizado()

        body = request.get_json(silent=True) or {}
        agent_id = str(
            body.get("agent_id")
            or request.headers.get("X-Agent-Id")
            or ""
        ).strip()[:255] or None

        with engine.begin() as conn:
            _interromper_jobs_sem_heartbeat(conn)
            row = conn.execute(text("""
                WITH proximo AS (
                    SELECT j.id
                    FROM public.jobs j
                    JOIN public.robos r ON r.id = j.robo_id
                    WHERE j.status = 'aguardando'
                      AND r.ativo = TRUE
                    ORDER BY j.id ASC
                    FOR UPDATE OF j SKIP LOCKED
                    LIMIT 1
                )
                UPDATE public.jobs j
                SET
                    status = 'executando',
                    iniciado_em = NOW(),
                    ultimo_heartbeat = NOW(),
                    agent_id = COALESCE(:agent_id, j.agent_id),
                    erro = NULL
                FROM proximo, public.robos r
                WHERE j.id = proximo.id
                  AND r.id = j.robo_id
                RETURNING
                    j.id,
                    j.robo_id,
                    j.solicitado_por,
                    j.status,
                    j.criado_em,
                    j.iniciado_em,
                    j.finalizado_em,
                    j.erro,
                    j.parametros,
                    j.ultimo_heartbeat,
                    j.agent_id,
                    r.codigo AS robo_codigo,
                    r.nome AS robo_nome
            """), {"agent_id": agent_id}).mappings().first()

        if not row:
            return jsonify({"ok": True, "job": None})

        log(
            f"BI Agent reservou Job #{row['id']} | robô: {row['robo_codigo']} | "
            f"agent_id: {row.get('agent_id') or 'não informado'}",
            "INFO",
        )
        return jsonify({"ok": True, "job": _job_publico(row)})

    except RuntimeError as e:
        log(f"Configuração do BI Agent inválida: {e}", "ERRO")
        return jsonify({"ok": False, "erro": "BI Agent não configurado no servidor."}), 503
    except Exception as e:
        log(f"Erro ao reservar job para BI Agent: {e}", "ERRO")
        return jsonify({"ok": False, "erro": "Erro interno ao reservar atualização."}), 500


@app.route("/api/agent/jobs/<int:job_id>/heartbeat", methods=["POST"])
def api_agent_heartbeat_job(job_id):
    """Atualiza o último sinal de vida de um job que continua executando."""
    try:
        if not _agent_autorizado():
            return _resposta_agent_nao_autorizado()

        body = request.get_json(silent=True) or {}
        agent_id = str(
            body.get("agent_id")
            or request.headers.get("X-Agent-Id")
            or ""
        ).strip()[:255] or None

        with engine.begin() as conn:
            row = conn.execute(text("""
                UPDATE public.jobs
                SET
                    ultimo_heartbeat = NOW(),
                    agent_id = COALESCE(:agent_id, agent_id)
                WHERE id = :job_id
                  AND status = 'executando'
                RETURNING
                    id,
                    status,
                    ultimo_heartbeat,
                    agent_id
            """), {
                "job_id": job_id,
                "agent_id": agent_id,
            }).mappings().first()

        if not row:
            return jsonify({
                "ok": False,
                "erro": "Job não encontrado ou não está em execução."
            }), 409

        return jsonify({
            "ok": True,
            "job": _job_publico(row),
        })

    except RuntimeError as e:
        log(f"Configuração do BI Agent inválida no heartbeat: {e}", "ERRO")
        return jsonify({"ok": False, "erro": "BI Agent não configurado no servidor."}), 503
    except Exception as e:
        log(f"Erro no heartbeat do Job #{job_id}: {e}", "ERRO")
        return jsonify({"ok": False, "erro": "Erro interno ao registrar heartbeat."}), 500


@app.route("/api/agent/jobs/<int:job_id>/finish", methods=["POST"])
def api_agent_finish_job(job_id):
    """Recebe do Agent o resultado final de um job que estava executando."""
    try:
        if not _agent_autorizado():
            return _resposta_agent_nao_autorizado()

        body = request.get_json(silent=True) or {}
        status = str(body.get("status") or "").strip().lower()
        if status not in {"concluido", "erro"}:
            return jsonify({
                "ok": False,
                "erro": "status deve ser 'concluido' ou 'erro'."
            }), 400

        erro = body.get("erro")
        if status == "concluido":
            erro = None
        elif erro is None:
            erro = "O robô terminou com erro sem mensagem adicional."
        else:
            erro = str(erro)[-20000:]

        agent_id = str(
            body.get("agent_id")
            or request.headers.get("X-Agent-Id")
            or ""
        ).strip()[:255] or None

        with engine.begin() as conn:
            row = conn.execute(text("""
                UPDATE public.jobs
                SET
                    status = :status,
                    finalizado_em = NOW(),
                    ultimo_heartbeat = NOW(),
                    agent_id = COALESCE(:agent_id, agent_id),
                    erro = :erro
                WHERE id = :job_id
                  AND status = 'executando'
                RETURNING
                    id,
                    robo_id,
                    solicitado_por,
                    status,
                    criado_em,
                    iniciado_em,
                    finalizado_em,
                    erro,
                    parametros,
                    ultimo_heartbeat,
                    agent_id
            """), {
                "job_id": job_id,
                "status": status,
                "erro": erro,
                "agent_id": agent_id,
            }).mappings().first()

        if not row:
            return jsonify({
                "ok": False,
                "erro": "Job não encontrado ou não está em execução."
            }), 409

        log(f"BI Agent finalizou Job #{job_id} com status {status}.", "INFO")
        return jsonify({"ok": True, "job": _job_publico(row)})

    except RuntimeError as e:
        log(f"Configuração do BI Agent inválida ao finalizar job: {e}", "ERRO")
        return jsonify({"ok": False, "erro": "BI Agent não configurado no servidor."}), 503
    except Exception as e:
        log(f"Erro ao finalizar Job #{job_id}: {e}", "ERRO")
        return jsonify({"ok": False, "erro": "Erro interno ao finalizar atualização."}), 500


