if __name__ == "__main__":
    cfg = load_config()

    if not STATUS_FILE.exists():
        salvar_status(estado_padrao())
    else:
        data = carregar_estado(scan_pastas=True)

        # Se a API foi desligada no meio de uma atualização, limpa status preso.
        if data.get("execucao", {}).get("status") == "executando":
            data["execucao"] = estado_padrao()["execucao"]

            for rid, rel in data.get("relatorios", {}).items():
                if str(rel.get("status", "")).lower() in ["atualizando", "em andamento", "executando"]:
                    rel["status"] = "Aguardando"

        salvar_status(data)

    print("=" * 80)
    print("Portal BI API V2")
    print(f"VERSÃO: {APP_VERSION}")
    print(f"APP.PY: {APP_FILE}")
    print(f"URL: {cfg['api']['public_url']}")
    print(f"CHAMADOS: {cfg['api']['public_url']}/api/chamados/health")
    print("=" * 80)

    app.run(
        host=cfg["api"]["host"],
        port=int(cfg["api"]["port"]),
        debug=False,
        threaded=True,
    )
